package dev.underthebedrock.horror;
import org.bukkit.entity.Player;import java.util.Locale;import java.util.Optional;
/** Contextual private-to-player Null reactions. Its recollections are grounded in saved evidence. */
public final class NullIntelligence {
 public Optional<String> respond(Player player,String message,PlayerHorrorMemory m){String t=message.toLowerCase(Locale.ROOT);StoryChapter c=StoryChapter.forPlayer(m);
  if(has(t,"what did i find","what have i found","evidence","the clue","the recording","do you remember","remember what")){if(m.discoveredClueCount()==0)return Optional.of("§8You have not found anything worth remembering.");return Optional.of(switch(m.lastClueId()){
   case "first_signal"->"§8You heard it answer. You still called it a recording.";case "false_exit"->"§8You found the exit. It was facing inward.";case "three_marks"->"§8Three marks. You counted them in the wrong order.";case "name_fragment"->"§8You are close to remembering the name. Don't say it.";case "recording"->"§8You listened to the part I told you not to.";case "final_address"->"§8You came back to the place you haven't visited yet.";case "creator_mark"->"§8The first stone remembers a hand the records do not.";case "world_before"->"§8He made the boundaries. He did not make what crossed them.";case "removal_order"->"§8The order was written before the erasure. It was never completed.";case "erasure"->"§8It did not kill him. It made the world unable to remember him.";case "last_witness"->"§8He tried to erase me. I erased him first.";default->"§8I remember what you chose to keep.";});}
  if(has(t,"where are you","show yourself","come here","null"))return Optional.of(switch(c){case ARRIVAL,ANOMALIES->"§8...you are looking in the wrong direction.";case SUSPICION,INVESTIGATION->"§8You keep asking as if I owe you an answer.";case NULL_INFLUENCE->"§8I was here before you decided to look.";case DEEP_EXPLORATION->"§8You finally walked far enough to hear me.";});
  if(has(t,"not afraid","not scared","i know you're there"))return Optional.of(switch(c){case ARRIVAL,ANOMALIES->"§8§oYou sound certain.";case SUSPICION,INVESTIGATION->"§8Then why did you stop walking?";case NULL_INFLUENCE->"§8You said that last time, too.";case DEEP_EXPLORATION->"§8Fear is not the thing I am waiting for.";});
  if(has(t,"hate you","stupid","kill you","coward","you can't"))return Optional.of(c.ordinal()>=StoryChapter.NULL_INFLUENCE.ordinal()?"§8§oCareful. I remember how you speak to me.":"§8§oThat was unnecessary.");
  if(has(t,"hello","hi null","anyone there"))return Optional.of(c.ordinal()>=StoryChapter.INVESTIGATION.ordinal()?"§8You already know the answer.":"§8...");return Optional.empty();}
 private boolean has(String t,String...terms){for(String s:terms)if(t.contains(s))return true;return false;}
}